class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        from collections import deque

        # Initialize the graph
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        answer = []

        for u, v in queries:
            graph[u].append(v)  # Add the new road

            # BFS to find the shortest path from 0 to n-1
            visited = [False] * n
            queue = deque()
            queue.append((0, 0))  # (node, distance)
            visited[0] = True

            while queue:
                node, dist = queue.popleft()
                if node == n - 1:
                    answer.append(dist)
                    break
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append((neighbor, dist + 1))

        return answer

class Solution:
    def subsequenceCount(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        o = 0
        for num in nums:
            if num % 2 == 1:
                o += 1
        e = len(nums) - o
        return pow(2, o + e - 1, MOD)

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        row, col = 0, 0
        for cmd in commands:
            if cmd == "UP":
                row -= 1
            elif cmd == "DOWN":
                row += 1
            elif cmd == "LEFT":
                col -= 1
            elif cmd == "RIGHT":
                col += 1
        return row * n + col

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        # dp[i][a] represents the number of ways to have arr1[i] = a
        dp = [{} for _ in range(n)]

        # Initialize for the first index
        for a in range(nums[0] + 1):
            dp[0][a] = 1

        for i in range(1, n):
            for a in range(nums[i] + 1):
                b = nums[i] - a
                # Check if there exists a previous value a_prev such that a_prev <= a and b_prev >= b
                for a_prev in dp[i-1]:
                    b_prev = nums[i-1] - a_prev
                    if a_prev <= a and b_prev >= b:
                        dp[i][a] = (dp[i].get(a, 0) + dp[i-1][a_prev]) % MOD

        # Sum all possibilities for the last index
        return sum(dp[-1].values()) % MOD

class Solution:
    def minimumCost(self, target: str, words: List[str], costs: List[int]) -> int:
        n = len(target)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(n):
            if dp[i] == float('inf'):
                continue
            for j in range(len(words)):
                word = words[j]
                cost = costs[j]
                if target.startswith(word, i):
                    if dp[i + len(word)] > dp[i] + cost:
                        dp[i + len(word)] = dp[i] + cost

        return dp[n] if dp[n] != float('inf') else -1

class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        results = []

        for i in range(n - k + 1):
            subarray = nums[i:i + k]
            is_consecutive = True
            is_sorted = True

            # Check if elements are consecutive and sorted
            for j in range(1, k):
                if subarray[j] != subarray[j - 1] + 1:
                    is_consecutive = False
                if subarray[j] <= subarray[j - 1]:
                    is_sorted = False

            if is_consecutive and is_sorted:
                results.append(subarray[-1])
            else:
                results.append(-1)

        return results

