class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        if n == 1:
            # Check all single-digit numbers from 9 down to 1
            for i in range(9, 0, -1):
                if i % k == 0:
                    return str(i)
            return ""

        # Helper function to generate palindromes of length n
        def generate_palindromes():
            half_length = (n + 1) // 2
            start = 10 ** (half_length - 1)
            end = 10 ** half_length - 1

            for i in range(end, start - 1, -1):
                s = str(i)
                if n % 2 == 0:
                    palindrome = s + s[::-1]
                else:
                    palindrome = s + s[-2::-1]
                yield int(palindrome)

        # Iterate through generated palindromes and find the largest divisible by k
        for pal in generate_palindromes():
            if pal % k == 0:
                return str(pal)

        return ""

class Solution:
    def countKConstraintSubstrings(self, s: str, k: int, queries: List[List[int]]) -> List[int]:
        n = len(s)
        # Precompute prefix sums for 0s and 1s
        prefix_zeros = [0] * (n + 1)
        prefix_ones = [0] * (n + 1)

        for i in range(n):
            prefix_zeros[i + 1] = prefix_zeros[i] + (1 if s[i] == '0' else 0)
            prefix_ones[i + 1] = prefix_ones[i] + (1 if s[i] == '1' else 0)

        result = []

        for l, r in queries:
            count = 0
            # Iterate over all possible starting points in [l, r]
            for start in range(l, r + 1):
                zeros = 0
                ones = 0
                # Expand the substring from start to end
                for end in range(start, r + 1):
                    if s[end] == '0':
                        zeros += 1
                    else:
                        ones += 1
                    # Check if the substring satisfies the k-constraint
                    if zeros <= k or ones <= k:
                        count += 1
            result.append(count)

        return result

class Solution:
    def getFinalState(self, nums: List[int], k: int, multiplier: int) -> List[int]:
        for _ in range(k):
            min_val = min(nums)
            idx = nums.index(min_val)
            nums[idx] *= multiplier
        return nums

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        from itertools import permutations

        def get_all_permutations(num):
            s = str(num)
            perms = set()
            # Add the original number
            perms.add(s)
            # Generate all permutations with exactly one swap
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    swapped = list(s)
                    swapped[i], swapped[j] = swapped[j], swapped[i]
                    perms.add("".join(swapped))
            return perms

        count = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                perm1 = get_all_permutations(nums[i])
                perm2 = get_all_permutations(nums[j])
                if perm1 & perm2:
                    count += 1
        return count

class Solution:
    def minLargest(self, nums1: List[int], nums2: List[int]) -> int:
        # Count the number of 0s and 1s in both arrays
        count_0_1 = [0, 0]
        count_0_2 = [0, 0]

        for num in nums1:
            if num == 0:
                count_0_1[0] += 1
            else:
                count_0_1[1] += 1

        for num in nums2:
            if num == 0:
                count_0_2[0] += 1
            else:
                count_0_2[1] += 1

        # Initialize the current even and odd numbers to be assigned
        even = 2
        odd = 1
        max_num = 0

        # Assign numbers to nums1
        for _ in range(count_0_1[0]):
            max_num = max(max_num, even)
            even += 2

        for _ in range(count_0_1[1]):
            max_num = max(max_num, odd)
            odd += 2

        # Assign numbers to nums2
        for _ in range(count_0_2[0]):
            max_num = max(max_num, even)
            even += 2

        for _ in range(count_0_2[1]):
            max_num = max(max_num, odd)
            odd += 2

        return max_num

class Solution:
    def stringHash(self, s: str, k: int) -> str:
        result = []
        n = len(s)
        for i in range(0, n, k):
            substring = s[i:i+k]
            total = sum(ord(ch) - ord('a') for ch in substring)
            hashed_char = total % 26
            result.append(chr(hashed_char + ord('a')))
        return ''.join(result)

class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        from itertools import permutations

        def is_k_palindromic(digits):
            # Check if digits can be rearranged to form a palindrome
            freq = {}
            for d in digits:
                freq[d] = freq.get(d, 0) + 1

            odd_count = 0
            for count in freq.values():
                if count % 2 != 0:
                    odd_count += 1
            return odd_count <= 1

        def is_divisible_by_k(digits, k):
            num = int(''.join(map(str, digits)))
            return num % k == 0

        count = 0
        # Generate all possible combinations of digits with length n
        for digits in permutations(range(10), n):
            if digits[0] == 0:
                continue  # Skip numbers with leading zeros
            if is_k_palindromic(digits) and is_divisible_by_k(digits, k):
                count += 1

        return count

class Solution:
    def resultsArray(self, queries: List[List[int]], k: int) -> List[int]:
        import heapq

        result = []
        max_heap = []

        for x, y in queries:
            distance = abs(x) + abs(y)
            # Push the distance into the max-heap
            heapq.heappush(max_heap, -distance)

            # If the heap size exceeds k, remove the largest element
            if len(max_heap) > k:
                heapq.heappop(max_heap)

            # If there are fewer than k obstacles, append -1
            if len(max_heap) < k:
                result.append(-1)
            else:
                # The kth smallest distance is the largest in the heap (negative of the top)
                result.append(-max_heap[0])

        return result

class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])
        self.max_score = 0

        def backtrack(row, used_values, current_sum):
            if row == rows:
                self.max_score = max(self.max_score, current_sum)
                return
            for col in range(cols):
                value = grid[row][col]
                if value not in used_values:
                    used_values.add(value)
                    backtrack(row + 1, used_values, current_sum + value)
                    used_values.remove(value)

        backtrack(0, set(), 0)
        return self.max_score

class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        prefix_xor = [0] * (n + 1)
        for i in range(n):
            prefix_xor[i + 1] = prefix_xor[i] ^ nums[i]

        result = []
        for l, r in queries:
            max_xor = 0
            for i in range(l, r + 1):
                for j in range(i, r + 1):
                    current_xor = prefix_xor[j + 1] ^ prefix_xor[i]
                    if current_xor > max_xor:
                        max_xor = current_xor
            result.append(max_xor)
        return result

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        max_score = 0
        max_val = 0
        for i in range(1, n):
            max_val = max(max_val, nums[i-1])
            max_score += max_val
        return max_score

