class Solution:
    def findSafeWalk(self, grid: List[List[int]], health: int) -> bool:
        m, n = len(grid), len(grid[0])
        visited = [[False] * n for _ in range(m)]

        def dfs(i, j, curr_health):
            if i < 0 or i >= m or j < 0 or j >= n or visited[i][j]:
                return False
            if (i, j) == (m - 1, n - 1):
                return curr_health >= 1
            visited[i][j] = True
            directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
            for dx, dy in directions:
                ni, nj = i + dx, j + dy
                new_health = curr_health - grid[ni][nj]
                if new_health >= 1 and dfs(ni, nj, new_health):
                    return True
            visited[i][j] = False
            return False

        return dfs(0, 0, health)

class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # dp[i][j] represents the maximum OR value for a subsequence of length j ending at index i
        dp = [[0] * (k + 1) for _ in range(n)]

        # Initialize dp for subsequences of length 1
        for i in range(n):
            dp[i][1] = nums[i]

        # Fill dp for subsequences of length > 1
        for length in range(2, k + 1):
            for i in range(n):
                for j in range(i):
                    dp[i][length] = max(dp[i][length], dp[j][length - 1] | nums[i])

        # Now find the best pair of subsequences of length k
        max_xor = 0
        for i in range(n):
            for j in range(i):
                # Check if there are k elements before i and k elements after j
                if dp[j][k] != 0 and dp[i][k] != 0:
                    current_xor = (dp[j][k]) ^ (dp[i][k])
                    max_xor = max(max_xor, current_xor)

        return max_xor

class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        from functools import lru_cache

        # Sort the coordinates based on x and y
        coordinates.sort()
        n = len(coordinates)

        # Memoization cache
        @lru_cache(maxsize=None)
        def dfs(i):
            x, y = coordinates[i]
            max_len = 1  # At least the point itself
            for j in range(i + 1, n):
                nx, ny = coordinates[j]
                if nx > x and ny > y:
                    max_len = max(max_len, 1 + dfs(j))
            return max_len

        return dfs(k)

class Solution:
    def getSneakyNumbers(self, nums: List[int]) -> List[int]:
        freq = {}
        for num in nums:
            if num in freq:
                freq[num] += 1
            else:
                freq[num] = 1
        result = [num for num, count in freq.items() if count == 2]
        return result

class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        from collections import defaultdict

        # Step 1: Collect all possible prefixes from words
        prefixes = set()
        for word in words:
            for i in range(1, len(word) + 1):
                prefixes.add(word[:i])

        n = len(target)
        # Step 2: Initialize DP array
        dp = [float('inf')] * (n + 1)
        dp[0] = 0  # Base case: 0 characters require 0 strings

        # Step 3: Fill DP array
        for i in range(1, n + 1):
            for j in range(i):
                if target[j:i] in prefixes:
                    dp[i] = min(dp[i], dp[j] + 1)

        return dp[n] if dp[n] != float('inf') else -1

class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        from collections import defaultdict
        import sys

        # Step 1: Collect all unique prefixes from words
        prefixes = set()
        for word in words:
            for i in range(1, len(word) + 1):
                prefixes.add(word[:i])

        n = len(target)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        # Step 2: Update the DP array
        for i in range(n):
            if dp[i] == float('inf'):
                continue
            for prefix in prefixes:
                if target[i:i + len(prefix)] == prefix:
                    if i + len(prefix) <= n:
                        dp[i + len(prefix)] = min(dp[i + len(prefix)], dp[i] + 1)

        return dp[n] if dp[n] != float('inf') else -1

class Solution:
    def reportSpam(self, message: List[str], bannedWords: List[str]) -> bool:
        banned_set = set(bannedWords)
        count = 0
        for word in message:
            if word in banned_set:
                count += 1
                if count >= 2:
                    return True
        return False

class Solution:
    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        import math

        def max_reduction(worker_time, t):
            # Calculate the maximum x such that worker_time * x * (x + 1) // 2 <= t
            # Solve x^2 + x - 2t / worker_time <= 0
            # Using quadratic formula: x = [-1 + sqrt(1 + 8t / worker_time)] / 2
            if worker_time == 0:
                return 0
            max_x = (-1 + math.sqrt(1 + 8 * t / worker_time)) / 2
            return int(max_x)

        low = 0
        high = 0
        # Set an initial upper bound for binary search
        for time in workerTimes:
            high = max(high, time * mountainHeight * (mountainHeight + 1) // 2)

        while low < high:
            mid = (low + high) // 2
            total_reduction = 0
            for time in workerTimes:
                total_reduction += max_reduction(time, mid)
                if total_reduction >= mountainHeight:
                    break
            if total_reduction >= mountainHeight:
                high = mid
            else:
                low = mid + 1
        return low

class Solution:
    def getSum(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        total = 0
        current_sum = 0
        prev = None

        for num in nums:
            if prev is None:
                # Start of a new sequence
                current_sum = num
                total += num
            else:
                if abs(num - prev) == 1:
                    # Continue the current sequence
                    current_sum += num
                    total += current_sum
                else:
                    # Reset the sequence
                    current_sum = num
                    total += num
            prev = num

        return total % MOD

class Solution:
    def minElement(self, nums: List[int]) -> int:
        def sum_of_digits(n):
            return sum(int(digit) for digit in str(n))

        transformed = [sum_of_digits(num) for num in nums]
        return min(transformed)

class Solution:
    def maximumTotalSum(self, maximumHeight: List[int]) -> int:
        maximumHeight.sort(reverse=True)
        total = 0
        last_used = float('inf')

        for height in maximumHeight:
            if height < last_used:
                return -1
            total += height
            last_used = height - 1

        return total

class Solution:
    def validSequence(self, word1: str, word2: str) -> List[int]:
        n, m = len(word1), len(word2)
        res = []
        i = j = 0
        changes = 0

        while i < n and j < m:
            if word1[i] == word2[j]:
                res.append(i)
                i += 1
                j += 1
            else:
                # Check if we can make a change
                if changes < 1:
                    res.append(i)
                    i += 1
                    changes += 1
                    j += 1
                else:
                    # No more changes allowed; skip this character in word1
                    i += 1

        # If we have matched all characters in word2, return the result
        if j == m:
            return res
        else:
            return []

class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        n = len(s)
        m = len(pattern)
        for i in range(n - m + 1):
            diff = 0
            for j in range(m):
                if s[i + j] != pattern[j]:
                    diff += 1
                    if diff > 1:
                        break
            if diff <= 1:
                return i
        return -1

class Solution:
    def kthCharacter(self, k: int) -> str:
        word = "a"
        while len(word) < k:
            transformed = []
            for ch in word:
                next_char = chr(ord('a') + (ord(ch) - ord('a') + 1) % 26)
                transformed.append(next_char)
            word += ''.join(transformed)
        return word[k-1]

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}
        count = 0
        n = len(word)

        # Iterate over all possible starting indices
        for i in range(n):
            vowel_set = set()
            consonant_count = 0
            # Iterate over all possible ending indices
            for j in range(i, n):
                char = word[j]
                if char in vowels:
                    vowel_set.add(char)
                else:
                    consonant_count += 1
                # Check if all vowels are present and consonant count is exactly k
                if len(vowel_set) == 5 and consonant_count == k:
                    count += 1
        return count

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}
        n = len(word)
        count = 0
        left = 0
        vowel_freq = {}
        consonant_count = 0

        for right in range(n):
            char = word[right]
            if char in vowels:
                vowel_freq[char] = vowel_freq.get(char, 0) + 1
            else:
                consonant_count += 1

            # Check if we have all vowels and exactly k consonants
            while len(vowel_freq) == 5 and consonant_count == k:
                # Count all substrings starting from left to right
                count += n - right
                # Move left pointer to reduce the window size
                left_char = word[left]
                if left_char in vowels:
                    vowel_freq[left_char] -= 1
                    if vowel_freq[left_char] == 0:
                        del vowel_freq[left_char]
                else:
                    consonant_count -= 1
                left += 1

        return count

class Solution:
    def kthCharacter(self, k: int, operations: List[int]) -> str:
        # Start with the initial string "a"
        length = 1
        current_char = 'a'

        for op in operations:
            if op == 0:
                # Operation 0: Append a copy of the current string to itself
                length *= 2
            else:
                # Operation 1: Transform the current string and append it
                # Transform the current character
                if current_char == 'z':
                    transformed_char = 'a'
                else:
                    transformed_char = chr(ord(current_char) + 1)
                # Append the transformed character to the current string
                current_char = current_char + transformed_char
                length *= 2

            # Check if k is within the range of the current string
            if k <= length:
                continue
            else:
                # If k exceeds the length, it's not possible as per the constraints
                pass

        return current_char[k - 1]

class Solution:
    def remainingMethods(self, n: int, k: int, invocations: List[List[int]]) -> List[int]:
        from collections import defaultdict, deque

        # Step 1: Build reverse graph
        reverse_graph = defaultdict(list)
        for a, b in invocations:
            reverse_graph[b].append(a)

        # Step 2: Find all suspicious methods using BFS
        suspicious = set()
        queue = deque([k])
        while queue:
            current = queue.popleft()
            if current in suspicious:
                continue
            suspicious.add(current)
            for caller in reverse_graph[current]:
                if caller not in suspicious:
                    queue.append(caller)

        # Step 3: Check if any non-suspicious method invokes a suspicious method
        for a, b in invocations:
            if a not in suspicious and b in suspicious:
                return list(range(n))

        # Step 4: Return the remaining methods
        return [i for i in range(n) if i not in suspicious]

class Solution:
    def lastMarkedNodes(self, edges: List[List[int]]) -> List[int]:
        from collections import deque, defaultdict

        n = len(edges) + 1
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        result = []

        for start in range(n):
            visited = [False] * n
            queue = deque()
            queue.append(start)
            visited[start] = True
            last_marked = start

            while queue:
                size = len(queue)
                for _ in range(size):
                    node = queue.popleft()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)
                            last_marked = neighbor
            result.append(last_marked)

        return result

class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        ans = []
        for num in nums:
            # Subtract 1 from num
            val = num - 1
            # Clear all trailing 1s
            val &= val + 1
            if val == num - 1:
                ans.append(val)
            else:
                ans.append(-1)
        return ans

class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        ans = []
        for num in nums:
            # Check if there is at least one 0 bit in the binary representation
            if (num & (num + 1)) == num:
                ans.append(-1)
            else:
                # Find the position of the first 0 bit
                first_zero_pos = (num & -num).bit_length() - 1
                # Set all bits after the first zero to 0
                min_val = num & (~((1 << first_zero_pos) - 1))
                ans.append(min_val)
        return ans

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        # Precompute the positions of each character in the source
        from collections import defaultdict

        char_positions = defaultdict(list)
        for idx, ch in enumerate(source):
            char_positions[ch].append(idx)

        # Check if pattern is a subsequence of source
        def is_subsequence():
            p_idx = 0
            for s_idx in range(len(source)):
                if p_idx < len(pattern) and source[s_idx] == pattern[p_idx]:
                    p_idx += 1
            return p_idx == len(pattern)

        # If pattern is not a subsequence, return 0 (though input guarantees it is)
        if not is_subsequence():
            return 0

        # Try removing characters from targetIndices and count valid operations
        count = 0
        for idx in targetIndices:
            # Temporarily remove the character at idx
            temp_source = source[:idx] + source[idx+1:]
            # Check if pattern is still a subsequence
            p_idx = 0
            for s_idx in range(len(temp_source)):
                if p_idx < len(pattern) and temp_source[s_idx] == pattern[p_idx]:
                    p_idx += 1
            if p_idx == len(pattern):
                count += 1
        return count

class Solution:
    def kthLargestPerfectSubtree(self, root: Optional[TreeNode], k: int) -> int:
