class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # dp[i][last_move][diff] = number of ways to reach this state
        # i: current index, last_move: last move made by Bob (0=F, 1=W, 2=E), diff: score difference (Bob - Alice)
        # Since the maximum possible score difference is n, we'll limit the range of diff from -n to n
        dp = [{} for _ in range(n + 1)]

        # Initialize the first round
        for move in range(3):
            alice_move = s[0]
            bob_score = 0
            alice_score = 0

            if move == 0:  # Bob chooses F
                if alice_move == 'E':
                    bob_score += 1
            elif move == 1:  # Bob chooses W
                if alice_move == 'F':
                    bob_score += 1
            elif move == 2:  # Bob chooses E
                if alice_move == 'W':
                    bob_score += 1

            diff = bob_score - alice_score
            dp[0][move] = {diff: 1}

        # Fill the DP table
        for i in range(1, n):
            current_char = s[i]
            for prev_move in range(3):
                for diff in dp[i - 1][prev_move]:
                    count = dp[i - 1][prev_move][diff]
                    for curr_move in range(3):
                        if curr_move == prev_move:
                            continue  # Bob cannot choose the same move consecutively

                        bob_score = 0
                        alice_score = 0

                        if curr_move == 0:  # Bob chooses F
                            if current_char == 'E':
                                bob_score += 1
                        elif curr_move == 1:  # Bob chooses W
                            if current_char == 'F':
                                bob_score += 1
                        elif curr_move == 2:  # Bob chooses E
                            if current_char == 'W':
                                bob_score += 1

                        new_diff = diff + bob_score - alice_score
                        if new_diff not in dp[i].get(curr_move, {}):
                            dp[i][curr_move][new_diff] = 0
                        dp[i][curr_move][new_diff] = (dp[i][curr_move][new_diff] + count) % MOD

        # Sum all sequences where Bob's score is strictly greater than Alice's
        result = 0
        for move in range(3):
            for diff in dp[n - 1][move]:
                if diff > 0:
                    result = (result + dp[n - 1][move][diff]) % MOD

        return result

class Solution:
    def minConnectedGroups(self, intervals: List[List[int]], k: int) -> int:
        # Step 1: Sort intervals by start time
        intervals.sort()

        # Step 2: Merge overlapping or adjacent intervals
        merged = []
        for interval in intervals:
            if not merged:
                merged.append(interval)
            else:
                last_start, last_end = merged[-1]
                curr_start, curr_end = interval
                if curr_start <= last_end:
                    # Overlapping or adjacent, merge them
                    merged[-1][1] = max(last_end, curr_end)
                else:
                    merged.append(interval)

        # Step 3: Count the number of connected groups initially
        num_groups = len(merged)

        # Step 4: Check for gaps between merged intervals and see if we can bridge them with the new interval
        for i in range(1, len(merged)):
            prev_end = merged[i-1][1]
            curr_start = merged[i][0]
            gap = curr_start - prev_end

            # If there is a gap, check if we can bridge it with the new interval
            if gap > 0:
                # The new interval must cover the gap, so its length must be at least gap
                if k >= gap:
                    # We can bridge the gap, reducing the number of connected groups by 1
                    num_groups -= 1

        return num_groups

class Solution:
    def stringSequence(self, target: str) -> List[str]:
        result = []
        current = ""
        for ch in target:
            # Append 'a' until the length of current matches the length of the target up to this point
            while len(current) < len(result) + 1:
                current += "a"
                result.append(current)
            # Increment the last character to match the target character
            while current[-1] != ch:
                current = current[:-1] + chr(ord(current[-1]) + 1)
                result.append(current)
        return result

class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        from collections import defaultdict

        n = len(s)
        total = 0
        freq = defaultdict(int)

        # Count the frequency of each character in the entire string
        for ch in s:
            freq[ch] += 1

        # For each character that appears at least k times, find the number of substrings where it appears at least k times
        for ch in freq:
            if freq[ch] >= k:
                # Use sliding window to count substrings with at least k occurrences of 'ch'
                left = 0
                count = 0
                for right in range(n):
                    if s[right] == ch:
                        count += 1
                    # Move left pointer until the count of 'ch' is less than k
                    while count >= k:
                        # All substrings starting from left to right are valid
                        total += n - right
                        if s[left] == ch:
                            count -= 1
                        left += 1

        return total

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        from collections import defaultdict

        # Precompute the number of operations to reduce a number to 1
        max_num = max(nums)
        ops = [0] * (max_num + 1)

        for i in range(2, max_num + 1):
            # Find the greatest proper divisor of i
            gpd = i // 2
            while gpd > 0:
                if i % gpd == 0:
                    break
                gpd -= 1
            ops[i] = ops[gpd] + 1

        # Now, we need to transform nums into a non-decreasing sequence
        # We will try to reduce each number to the smallest possible value that maintains the non-decreasing order
        res = 0
        prev = 1  # Start with the smallest possible value

        for num in nums:
            # Try to reduce num to the smallest value >= prev
            current = num
            while current >= prev:
                if current == 1:
                    break
                # Find the greatest proper divisor of current
                gpd = current // 2
                while gpd > 0:
                    if current % gpd == 0:
                        break
                    gpd -= 1
                current = gpd
                res += 1
            if current < prev:
                return -1
            prev = current

        return res

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        from collections import defaultdict

        # Build the tree with children sorted in increasing order
        tree = defaultdict(list)
        for i in range(1, len(parent)):
            tree[parent[i]].append(i)

        # Function to perform DFS and return the generated string
        def dfs(node):
            res = []
            for child in tree[node]:
                res.append(dfs(child))
            res.append(s[node])
            return ''.join(res)

        # Generate the answer array
        answer = []
        for i in range(len(parent)):
            dfs_str = dfs(i)
            # Check if the string is a palindrome
            is_palindrome = dfs_str == dfs_str[::-1]
            answer.append(is_palindrome)

        return answer

class Solution:
    def possibleStringCount(self, word: str) -> int:
        res = 1
        i = 0
        n = len(word)
        while i < n:
            j = i
            while j < n and word[j] == word[i]:
                j += 1
            count = j - i
            res *= count
            i = j
        return res

class Solution:
    def findSubtreeSizes(self, parent: List[int], s: str) -> List[int]:
        from collections import defaultdict

        n = len(parent)
        children = defaultdict(list)

        # Build the tree
        for i in range(1, n):
            children[parent[i]].append(i)

        # Track the size of each subtree
        subtree_size = [1] * n

        # Helper function to perform DFS and calculate subtree sizes
        def dfs(node):
            for child in children[node]:
                dfs(child)
                subtree_size[node] += subtree_size[child]

        # Find the closest ancestor with the same character and update the tree
        # We will store the new parent for each node
        new_parent = [0] * n

        # Traverse the tree and find the closest ancestor with the same character
        def find_closest_ancestor(node, path):
            for ancestor in path:
                if s[ancestor] == s[node]:
                    return ancestor
            return -1

        # Perform a DFS to find the closest ancestor for each node
        def dfs_find_ancestor(node, path):
            # Find the closest ancestor with the same character
            closest_ancestor = find_closest_ancestor(node, path)
            if closest_ancestor != -1:
                new_parent[node] = closest_ancestor
            else:
                new_parent[node] = parent[node]

            # Update the path with the current node
            path.append(node)

            # Recursively visit children
            for child in children[node]:
                dfs_find_ancestor(child, path)

            # Remove the current node from the path
            path.pop()

        # Start DFS from the root
        dfs_find_ancestor(0, [])

        # Rebuild the tree with the new parent relationships
        new_children = defaultdict(list)
        for i in range(n):
            if i != 0:
                new_children[new_parent[i]].append(i)

        # Calculate the size of each subtree in the new tree
        def dfs_new_tree(node):
            for child in new_children[node]:
                dfs_new_tree(child)
                subtree_size[node] += subtree_size[child]

        dfs_new_tree(0)

        return subtree_size

class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # Initialize DP table
        dp = [[0] * n for _ in range(k + 1)]

        # Base case: Day 0
        for j in range(n):
            dp[0][j] = stayScore[0][j]

        # Fill DP table for remaining days
        for i in range(1, k + 1):
            for curr in range(n):
                # Option 1: Stay in current city
                stay_score = stayScore[i][curr]
                # Option 2: Travel from any other city
                max_travel_score = max(dp[i-1][prev] + travelScore[prev][curr] for prev in range(n) if prev != curr)
                dp[i][curr] = max(stay_score, max_travel_score)

        # Return the maximum score on day k
        return max(dp[k])

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        from math import gcd
        from functools import reduce

        def lcm(a, b):
            return a * b // gcd(a, b)

        def compute_lcm(arr):
            if not arr:
                return 0
            return reduce(lcm, arr)

        def compute_gcd(arr):
            if not arr:
                return 0
            return reduce(gcd, arr)

        n = len(nums)
        if n == 0:
            return 0
        if n == 1:
            return nums[0] * nums[0]

        max_score = 0

        # Compute factor score for the original array
        current_gcd = compute_gcd(nums)
        current_lcm = compute_lcm(nums)
        max_score = current_gcd * current_lcm

        # Try removing each element
        for i in range(n):
            new_nums = nums[:i] + nums[i+1:]
            current_gcd = compute_gcd(new_nums)
            current_lcm = compute_lcm(new_nums)
            score = current_gcd * current_lcm
            if score > max_score:
                max_score = score

        return max_score

class Solution:
    def lengthAfterTransformations(self, s: str, t: int, nums: List[int]) -> int:
        MOD = 10**9 + 7
        from collections import Counter

        # Count initial occurrences of each character
        count = [0] * 26
        for ch in s:
            count[ord(ch) - ord('a')] += 1

        # Define the transformation matrix
        def multiply(a, b):
            result = [[0] * 26 for _ in range(26)]
            for i in range(26):
                for k in range(26):
                    if a[i][k]:
                        for j in range(26):
                            result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % MOD
            return result

        def power(mat, n):
            result = [[0] * 26 for _ in range(26)]
            for i in range(26):
                result[i][i] = 1
            while n > 0:
                if n % 2 == 1:
                    result = multiply(result, mat)
                mat = multiply(mat, mat)
                n //= 2
            return result

        # Build the transformation matrix
        trans = [[0] * 26 for _ in range(26)]
        for i in range(26):
            val = nums[i]
            for j in range(val):
                trans[i][(i + j + 1) % 26] += 1

        # Compute the transformation matrix raised to the power of t
        trans_pow = power(trans, t)

        # Apply the transformation to the initial count
        final_count = [0] * 26
        for i in range(26):
            for j in range(26):
                final_count[j] = (final_count[j] + count[i] * trans_pow[i][j]) % MOD

        # Sum all counts to get the final length
        return sum(final_count) % MOD

class Solution:
    def countOfArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        # Precompute the number of even and odd numbers in [1, m]
        even_count = m // 2
        odd_count = m - even_count

        # Precompute the number of pairs (a, b) where (a - 1)(b - 1) is odd
        # This happens when both a and b are even
        odd_pairs = even_count * even_count

        # Initialize DP table
        dp = [[[0] * (m + 1) for _ in range(k + 1)] for __ in range(n + 1)]

        # Base case: arrays of length 1 have 0 valid pairs
        for l in range(1, m + 1):
            dp[1][0][l] = 1

        # Fill DP table
        for i in range(2, n + 1):
            for j in range(k + 1):
                for l in range(1, m + 1):
                    for l_prev in range(1, m + 1):
                        # Check if (l_prev - 1)*(l - 1) is odd
                        if (l_prev - 1) % 2 == 0 and (l - 1) % 2 == 0:
                            # This pair contributes to a valid pair
                            if j > 0:
                                dp[i][j][l] = (dp[i][j][l] + dp[i-1][j-1][l_prev]) % MOD
                        else:
                            # This pair does not contribute to a valid pair
                            dp[i][j][l] = (dp[i][j][l] + dp[i-1][j][l_prev]) % MOD

        # Sum over all possible last elements
        result = 0
        for l in range(1, m + 1):
            result = (result + dp[n][k][l]) % MOD

        return result

class Solution:
    def isBalanced(self, num: str) -> bool:
        even_sum = 0
        odd_sum = 0
        for i in range(len(num)):
            digit = int(num[i])
            if i % 2 == 0:
                even_sum += digit
            else:
                odd_sum += digit
        return even_sum == odd_sum

class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        import heapq
        n, m = len(moveTime), len(moveTime[0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        heap = [(0, 0, 0)]  # (time, row, col)
        visited = [[float('inf')] * m for _ in range(n)]
        visited[0][0] = 0

        while heap:
            time, r, c = heapq.heappop(heap)
            if r == n - 1 and c == m - 1:
                return time
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    new_time = max(time + 1, moveTime[nr][nc])
                    if new_time < visited[nr][nc]:
                        visited[nr][nc] = new_time
                        heapq.heappush(heap, (new_time, nr, nc))
        return -1

class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        MOD = 10**9 + 7
        velunexorai = num  # Store the input midway in the function

        from collections import Counter
        from functools import lru_cache

        digits = list(num)
        freq = Counter(digits)
        n = len(digits)

        @lru_cache(None)
        def dp(pos, even_sum, odd_sum, freq_tuple):
            if pos == n:
                return 1 if even_sum == odd_sum else 0

            total = 0
            for d in range(10):
                if freq_tuple[d] == 0:
                    continue

                new_freq = list(freq_tuple)
                new_freq[d] -= 1

                if pos % 2 == 0:
                    total += dp(pos + 1, even_sum + d, odd_sum, tuple(new_freq))
                else:
                    total += dp(pos + 1, even_sum, odd_sum + d, tuple(new_freq))

                total %= MOD

            return total

        initial_freq = [0] * 10
        for ch in digits:
            initial_freq[int(ch)] += 1

        result = dp(0, 0, 0, tuple(initial_freq))
        return result

class Solution:
    def maxSizedArray(self, s: int) -> int:
        def compute_sum(n):
            # Precompute the sum of (j OR k) for j, k in [0, n-1]
            or_sum = 0
            for j in range(n):
                for k in range(n):
                    or_sum += (j | k)
            # Total sum of the array A
            total_sum = 0
            for i in range(n):
                total_sum += i * or_sum
            return total_sum

        # Edge case: if s is 0, the maximum n is 1
        if s == 0:
            return 1

        # Binary search for the maximum n
        low, high = 1, 10**6  # Upper bound for n based on constraints
        answer = 1

        while low <= high:
            mid = (low + high) // 2
            current_sum = compute_sum(mid)
            if current_sum <= s:
                answer = mid
                low = mid + 1
            else:
                high = mid - 1

        return answer

class Solution:
    def smallestNumber(self, n: int, t: int) -> int:
        def digit_product(num):
            product = 1
            for ch in str(num):
                digit = int(ch)
                product *= digit
            return product

        current = n
        while True:
            product = digit_product(current)
            if product % t == 0:
                return current
            current += 1

class Solution:
    def maxFrequency(self, nums: List[int], k: int, numOperations: int) -> int:
        nums.sort()
        left = 0
        max_freq = 0
        total_ops = 0

        for right in range(len(nums)):
            total_ops += k * (right - left)
            while total_ops > numOperations:
                total_ops -= k
                left += 1
            max_freq = max(max_freq, right - left + 1)

        return max_freq

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # Check if a subarray starting at index i is strictly increasing
        def is_increasing(i):
            for j in range(i, i + k - 1):
                if nums[j] >= nums[j + 1]:
                    return False
            return True

        # Iterate through possible starting indices for the first subarray
        for i in range(n - 2 * k + 1):
            if is_increasing(i) and is_increasing(i + k):
                return True
        return False

class Solution:
    def maxIncreasingSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        # Precompute the length of strictly increasing subarrays starting at each index
        incr = [1] * n
        for i in range(n - 2, -1, -1):
            if nums[i + 1] > nums[i]:
                incr[i] = incr[i + 1] + 1
            else:
                incr[i] = 1

        # Check for the maximum k
        max_k = 0
        for k in range(1, n):
            found = False
            for i in range(n - k):
                if incr[i] >= k and incr[i + k] >= k:
                    found = True
                    break
            if found:
                max_k = k
            else:
                break
        return max_k

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = int(s, 2)

        # Memoization cache for the number of steps to reduce a number to 1
        from functools import lru_cache

        @lru_cache(None)
        def count_steps(x):
            if x == 1:
                return 0
            steps = 0
            while x != 1 and steps <= k:
                x = bin(x).count('1')
                steps += 1
            return steps if x == 1 else float('inf')

        # Count how many numbers less than n are k-reducible
        result = 0
        for x in range(1, n):
            if count_steps(x) <= k:
                result += 1
        return result % MOD

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        operations = 0
        prev = nums[0]
        for num in nums[1:]:
            if num != prev:
                operations += 1
                prev = num
        return operations

class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Try all positions where nums[curr] == 0
        for curr in range(n):
            if nums[curr] != 0:
                continue

            # Try moving left first
            direction = -1
            temp_nums = nums[:]
            valid = True
            while True:
                if curr < 0 or curr >= n:
                    break
                if temp_nums[curr] == 0:
                    curr += direction
                else:
                    temp_nums[curr] -= 1
                    direction *= -1
                    curr += direction
            if all(x == 0 for x in temp_nums):
                count += 1

            # Try moving right
            direction = 1
            temp_nums = nums[:]
            valid = True
            while True:
                if curr < 0 or curr >= n:
                    break
                if temp_nums[curr] == 0:
                    curr += direction
                else:
                    temp_nums[curr] -= 1
                    direction *= -1
                    curr += direction
            if all(x == 0 for x in temp_nums):
                count += 1

        return count

class Solution:
    def isZeroArray(self, nums: List[int], queries: List[List[int]]) -> bool:
        n = len(nums)
        diff = [0] * (n + 1)

        for l, r in queries:
            diff[l] += 1
            if r + 1 < n:
                diff[r + 1] -= 1

        # Compute prefix sums to get the number of decrements at each index
        decrements = 0
        for i in range(n):
            decrements += diff[i]
            if nums[i] > decrements:
                return False

        return True

class Solution:
    def countSubmatrices(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        count = 0

        for i in range(m):
            # Check if the current row is non-increasing
            is_non_increasing = True
            for j in range(1, n):
                if grid[i][j] > grid[i][j - 1]:
                    is_non_increasing = False
                    break
            if not is_non_increasing:
                continue

            # Find the range of columns in this row where elements are <= k
            left = 0
            while left < n and grid[i][left] <= k:
                left += 1
            right = left

            # Count all submatrices ending at this row with valid column ranges
            for j in range(left):
                count += (j + 1)

        return count

class Solution:
    def canAliceWin(self, n: int) -> bool:
        if n < 10:
            return False
        stones = n - 10
        move = 9
        turn = 1  # 1 for Bob, -1 for Alice
        while stones > 0:
            if move > stones:
                return turn == -1
            stones -= move
            move -= 1
            turn *= -1
        return turn == -1

class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        # Initialize DP tables for each child
        dp1 = [[-1 for _ in range(n)] for _ in range(n)]
        dp2 = [[-1 for _ in range(n)] for _ in range(n)]
        dp3 = [[-1 for _ in range(n)] for _ in range(n)]

        # Child 1 starts at (0, 0)
        dp1[0][0] = fruits[0][0]
        # Child 2 starts at (0, n - 1)
        dp2[0][n - 1] = fruits[0][n - 1]
        # Child 3 starts at (n - 1, 0)
        dp3[n - 1][0] = fruits[n - 1][0]

        # Fill DP tables for each child
        for i in range(n):
            for j in range(n):
                if dp1[i][j] != -1:
                    # Move to (i+1, j), (i, j+1), (i+1, j+1)
                    for ni, nj in [(i + 1, j), (i, j + 1), (i + 1, j + 1)]:
                        if 0 <= ni < n and 0 <= nj < n:
                            if dp1[ni][nj] == -1 or dp1[ni][nj] < dp1[i][j] + fruits[ni][nj]:
                                dp1[ni][nj] = dp1[i][j] + fruits[ni][nj]

                if dp2[i][j] != -1:
                    # Move to (i+1, j-1), (i+1, j), (i+1, j+1)
                    for ni, nj in [(i + 1, j - 1), (i + 1, j), (i + 1, j + 1)]:
                        if 0 <= ni < n and 0 <= nj < n:
                            if dp2[ni][nj] == -1 or dp2[ni][nj] < dp2[i][j] + fruits[ni][nj]:
                                dp2[ni][nj] = dp2[i][j] + fruits[ni][nj]

                if dp3[i][j] != -1:
                    # Move to (i-1, j+1), (i, j+1), (i+1, j+1)
                    for ni, nj in [(i - 1, j + 1), (i, j + 1), (i + 1, j + 1)]:
                        if 0 <= ni < n and 0 <= nj < n:
                            if dp3[ni][nj] == -1 or dp3[ni][nj] < dp3[i][j] + fruits[ni][nj]:
                                dp3[ni][nj] = dp3[i][j] + fruits[ni][nj]

        # Collect fruits from the final cell (n-1, n-1)
        total_fruits = 0
        visited = set()
        for dp in [dp1, dp2, dp3]:
            if dp[n - 1][n - 1] != -1:
                if (n - 1, n - 1) not in visited:
                    total_fruits += dp[n - 1][n - 1]
                    visited.add((n - 1, n - 1))

        return total_fruits

class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        min_sum = float('inf')
        n = len(nums)

        for length in range(l, r + 1):
            for i in range(n - length + 1):
                subarray = nums[i:i+length]
                current_sum = sum(subarray)
                if current_sum > 0 and current_sum < min_sum:
                    min_sum = current_sum

        return min_sum if min_sum != float('inf') else -1

class Solution:
    def isPossibleToRearrange(self, s: str, t: str, k: int) -> bool:
        sub_len = len(s) // k
        s_substrings = [s[i:i+sub_len] for i in range(0, len(s), sub_len)]
        t_substrings = [t[i:i+sub_len] for i in range(0, len(t), sub_len)]

        from collections import Counter
        return Counter(s_substrings) == Counter(t_substrings)

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        # Apply operations greedily to minimize the sum
        for i in range(len(nums)):
            # Try operation 1 first if available
            if op1 > 0:
                # Divide by 2, rounding up
                new_val = (nums[i] + 1) // 2
                reduction = nums[i] - new_val
                nums[i] = new_val
                op1 -= 1
            # Try operation 2 if available and applicable
            elif op2 > 0 and nums[i] >= k:
                nums[i] -= k
                op2 -= 1
        return sum(nums)

class Solution:
    def smallestNumber(self, n: int) -> int:
        # Find the smallest k such that 2^k - 1 >= n
        k = n.bit_length()
        # If 2^(k-1) - 1 is less than n, then we need to use 2^k - 1
        if (1 << (k - 1)) - 1 < n:
            return (1 << k) - 1
        else:
            return (1 << (k - 1)) - 1

class Solution:
    def maxTargetNodes(self, edges1: List[List[int]], edges2: List[List[int]], k: int) -> List[int]:
        from collections import deque, defaultdict
        import sys
        sys.setrecursionlimit(10000)

        def build_tree(edges, n):
            tree = [[] for _ in range(n)]
            for u, v in edges:
                tree[u].append(v)
                tree[v].append(u)
            return tree

        def count_nodes_within_k(tree, n, k):
            res = [0] * n
            for start in range(n):
                visited = [False] * n
                q = deque()
                q.append((start, 0))
                visited[start] = True
                count = 0
                while q:
                    node, dist = q.popleft()
                    if dist <= k:
                        count += 1
                    else:
                        continue
                    for neighbor in tree[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            q.append((neighbor, dist + 1))
                res[start] = count
            return res

        n = len(edges1) + 1
        m = len(edges2) + 1

        tree1 = build_tree(edges1, n)
        tree2 = build_tree(edges2, m)

        count1 = count_nodes_within_k(tree1, n, k)
        count2 = count_nodes_within_k(tree2, m, k)

        result = [0] * n
        for i in range(n):
            max_val = 0
            for j in range(m):
                total = count1[i] + count2[j] - 1
                if total > max_val:
                    max_val = total
            result[i] = max_val
        return result

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        nums.sort()
        if k not in nums or any(num < k for num in nums):
            return -1

        operations = 0
        current_h = max(nums)

        while current_h > k:
            # Find the next valid h
            next_h = None
            for h in range(current_h - 1, k - 1, -1):
                # Check if all elements > h are the same
                greater_values = [num for num in nums if num > h]
                if len(set(greater_values)) == 1:
                    next_h = h
                    break
            if next_h is None:
                return -1
            operations += 1
            current_h = next_h

        return operations

class Solution:
    def findMinimumTime(self, strength: List[int], k: int) -> int:
        from itertools import permutations

        def calculate_time(order):
            time = 0
            x = 1
            current_energy = 0
            for s in order:
                # Calculate the time needed to accumulate enough energy to break this lock
                while current_energy < s:
                    current_energy += x
                    time += 1
                # Reset energy and increase x after breaking the lock
                current_energy = 0
                x += k
            return time

        # Try all permutations of the strength array to find the minimum time
        min_time = float('inf')
        for perm in permutations(strength):
            total_time = calculate_time(perm)
            if total_time < min_time:
                min_time = total_time
        return min_time

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        from collections import defaultdict

        parent = {}

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        # Sort the list
        nums.sort()

        # Initialize parent map
        for num in nums:
            parent[num] = num

        # Iterate through each number and check for possible connections
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                a = nums[i]
                b = nums[j]
                lcm = a * b // math.gcd(a, b)
                if lcm <= threshold:
                    union(a, b)

        # Count unique roots
        roots = set()
        for num in nums:
            roots.add(find(num))

        return len(roots)

class Solution:
    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = [0] * n
        for i in range(n):
            if nums[i] > 0:
                new_index = (i + nums[i]) % n
                result[i] = nums[new_index]
            elif nums[i] < 0:
                new_index = (i - abs(nums[i])) % n
                result[i] = nums[new_index]
            else:
                result[i] = 0
        return result

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        from itertools import combinations

        # Group points by x-coordinate
        x_to_ys = {}
        for x, y in points:
            if x not in x_to_ys:
                x_to_ys[x] = []
            x_to_ys[x].append(y)

        # Check for pairs of x-values that have at least two y-values
        max_area = -1
        x_values = list(x_to_ys.keys())
        for i in range(len(x_values)):
            for j in range(i + 1, len(x_values)):
                x1, x2 = x_values[i], x_values[j]
                y_list1 = x_to_ys[x1]
                y_list2 = x_to_ys[x2]

                # Generate all combinations of two y-values from each x-value
                for y1, y2 in combinations(y_list1, 2):
                    for y3, y4 in combinations(y_list2, 2):
                        # Ensure the points are corners of a rectangle
                        if y1 == y3 or y1 == y4 or y2 == y3 or y2 == y4:
                            continue

                        # Define the rectangle's corners
                        points_rect = [[x1, y1], [x1, y2], [x2, y3], [x2, y4]]
                        # Sort the points for consistency
                        points_rect.sort()

                        # Check if any other point lies inside or on the border of the rectangle
                        is_valid = True
                        for p in points:
                            if p in points_rect:
                                continue
                            x, y = p
                            if x1 < x < x2 and y1 < y < y2:
                                is_valid = False
                                break
                            elif x == x1 or x == x2:
                                if y1 <= y <= y2:
                                    is_valid = False
                                    break
                            elif y == y1 or y == y2:
                                if x1 <= x <= x2:
                                    is_valid = False
                                    break

                        if is_valid:
                            area = abs(x2 - x1) * abs(y2 - y1)
                            max_area = max(max_area, area)

        return max_area

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        prefix_sum = 0
        min_prefix = {}
        max_sum = float('-inf')
        min_prefix[0] = -1  # Initialize for mod 0

        for i, num in enumerate(nums):
            prefix_sum += num
            mod = prefix_sum % k
            if mod in min_prefix:
                # Calculate the sum of the subarray from min_prefix[mod]+1 to i
                current_sum = prefix_sum - min_prefix[mod]
                max_sum = max(max_sum, current_sum)
            else:
                min_prefix[mod] = prefix_sum

        return max_sum

class Solution:
    def maxRectangleArea(self, xCoord: List[int], yCoord: List[int]) -> int:
        # Sort the coordinates
        x_sorted = sorted(xCoord)
        y_sorted = sorted(yCoord)

        # Create sets for quick lookup
        x_set = set(xCoord)
        y_set = set(yCoord)

        max_area = -1

        # Iterate through all pairs of x coordinates
        for i in range(len(x_sorted)):
            for j in range(i + 1, len(x_sorted)):
                x1 = x_sorted[i]
                x2 = x_sorted[j]

                # Iterate through all pairs of y coordinates
                for k in range(len(y_sorted)):
                    for l in range(k + 1, len(y_sorted)):
                        y1 = y_sorted[k]
                        y2 = y_sorted[l]

                        # Check if there are any points inside or on the border of the rectangle
                        valid = True
                        for x in x_set:
                            if x1 < x < x2:
                                for y in y_set:
                                    if y1 < y < y2:
                                        valid = False
                                        break
                                if not valid:
                                    break
                        if valid:
                            area = (x2 - x1) * (y2 - y1)
                            max_area = max(max_area, area)

        return max_area

class Solution:
    def minRunesToAdd(self, n: int, crystals: List[int], flowFrom: List[int], flowTo: List[int]) -> int:
        from collections import deque, defaultdict

        # Build the graph
        graph = defaultdict(list)
        for u, v in zip(flowFrom, flowTo):
            graph[u].append(v)

        # Set of crystal nodes
        crystal_set = set(crystals)

        # Track visited nodes
        visited = set()

        # BFS from all crystal nodes
        queue = deque()
        for crystal in crystals:
            if crystal not in visited:
                queue.append(crystal)
                visited.add(crystal)

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        # Count nodes that are not visited and not in crystal_set
        required = 0
        for i in range(n):
            if i not in visited and i not in crystal_set:
                required += 1

        return required

class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        max_time = 0
        result_index = events[0][0]
        prev_time = events[0][1]

        for i in range(1, len(events)):
            current_time = events[i][1]
            time_diff = current_time - prev_time
            if time_diff > max_time:
                max_time = time_diff
                result_index = events[i][0]
            elif time_diff == max_time:
                if events[i][0] < result_index:
                    result_index = events[i][0]
            prev_time = current_time

        return result_index

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
