        for i in range(1, n - 1):
            for j in range(i + 1, n):
                # Check if nums1 is a prefix of nums2
                is_prefix1 = True
                for k in range(len(nums[:i])):
                    if nums[k] != nums[i + k]:
                        is_prefix1 = False
                        break
                if is_prefix1:
                    count += 1
                    continue

                # Check if nums2 is a prefix of nums3
                is_prefix2 = True
                for k in range(len(nums[i:j])):
                    if nums[i + k] != nums[j + k]:
                        is_prefix2 = False
                        break
                if is_prefix2:
                    count += 1

        return count

