class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])

        # Initialize a 3D DP array: dp[i][j][x] = number of ways to reach (i, j) with XOR value x
        dp = [[[0] * 16 for _ in range(n)] for __ in range(m)]

        # Starting point: (0, 0)
        dp[0][0][grid[0][0]] = 1

        # Fill the DP table
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue  # Already initialized
                # Update current cell based on top or left cell
                for x in range(16):
                    if i > 0:
                        dp[i][j][x ^ grid[i][j]] = (dp[i][j][x ^ grid[i][j]] + dp[i-1][j][x]) % MOD
                    if j > 0:
                        dp[i][j][x ^ grid[i][j]] = (dp[i][j][x ^ grid[i][j]] + dp[i][j-1][x]) % MOD

        # Return the number of paths to (m-1, n-1) with XOR equal to k
        return dp[m-1][n-1][k]

class Solution:
    def checkValidCuts(self, n: int, rectangles: List[List[int]]) -> bool:
        # Extract all unique y-coordinates (for horizontal cuts)
        horizontal_cuts = set()
        for rect in rectangles:
            horizontal_cuts.add(rect[1])
            horizontal_cuts.add(rect[3])

        # Extract all unique x-coordinates (for vertical cuts)
        vertical_cuts = set()
        for rect in rectangles:
            vertical_cuts.add(rect[0])
            vertical_cuts.add(rect[2])

        # Check for valid horizontal cuts
        sorted_horizontal = sorted(horizontal_cuts)
        if len(sorted_horizontal) >= 2:
            # Check if we can split the grid into three parts with two horizontal cuts
            for i in range(1, len(sorted_horizontal) - 1):
                for j in range(i + 1, len(sorted_horizontal)):
                    y1 = sorted_horizontal[i]
                    y2 = sorted_horizontal[j]
                    if y1 > 0 and y2 < n and y1 < y2:
                        # Check if all rectangles are covered by the three regions
                        region1 = any(rect[1] >= 0 and rect[3] <= y1 for rect in rectangles)
                        region2 = any(rect[1] >= y1 and rect[3] <= y2 for rect in rectangles)
                        region3 = any(rect[1] >= y2 and rect[3] <= n for rect in rectangles)
                        if region1 and region2 and region3:
                            return True

        # Check for valid vertical cuts
        sorted_vertical = sorted(vertical_cuts)
        if len(sorted_vertical) >= 2:
            # Check if we can split the grid into three parts with two vertical cuts
            for i in range(1, len(sorted_vertical) - 1):
                for j in range(i + 1, len(sorted_vertical)):
                    x1 = sorted_vertical[i]
                    x2 = sorted_vertical[j]
                    if x1 > 0 and x2 < n and x1 < x2:
                        # Check if all rectangles are covered by the three regions
                        region1 = any(rect[0] >= 0 and rect[2] <= x1 for rect in rectangles)
                        region2 = any(rect[0] >= x1 and rect[2] <= x2 for rect in rectangles)
                        region3 = any(rect[0] >= x2 and rect[2] <= n for rect in rectangles)
                        if region1 and region2 and region3:
                            return True

        return False

class Solution:
    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        nums.sort()
        distinct_count = 0
        for num in nums:
            if distinct_count == 0 or num - k > nums[distinct_count - 1]:
                nums[distinct_count] = num
                distinct_count += 1
        return distinct_count

class Solution:
    def maximumMatchingIndices(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        matches = [i for i in range(n) if nums1[i] == nums2[i]]

        max_count = 0
        for k in range(n):
            count = 0
            for i in matches:
                if (i - k) % n == i:
                    count += 1
            max_count = max(max_count, count)

        return max_count

class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])
        operations = 0

        for j in range(n):
            for i in range(1, m):
                if grid[i][j] <= grid[i-1][j]:
                    needed = grid[i-1][j] + 1 - grid[i][j]
                    operations += needed
                    grid[i][j] += needed

        return operations

class Solution:
    def numberOfSubsequences(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0
        # Iterate over all possible values of p
        for p in range(n - 6):
            # Iterate over all possible values of q with q > p + 1
            for q in range(p + 2, n - 4):
                # Iterate over all possible values of r with r > q + 1
                for r in range(q + 2, n - 2):
                    # Iterate over all possible values of s with s > r + 1
                    for s in range(r + 2, n):
                        if nums[p] * nums[r] == nums[q] * nums[s]:
                            count += 1
        return count

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7
        # Initialize DP table
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[1][0] = m

        for i in range(2, n + 1):
            for j in range(k + 1):
                # Case 1: Add a new element that is different from the previous one
                dp[i][j] = dp[i - 1][j] * (m - 1) % MOD
                # Case 2: Add a new element that is the same as the previous one
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD

        return dp[n][k]

class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        # Split the pattern into prefix and suffix around the '*'
        star_index = p.index('*')
        prefix = p[:star_index]
        suffix = p[star_index+1:]

        # Iterate over all possible starting positions in s for the prefix
        for i in range(len(s) - len(prefix) + 1):
            if s[i:i+len(prefix)] == prefix:
                # Check if there is a valid ending position for the suffix
                for j in range(i + len(prefix), len(s) - len(suffix) + 1):
                    if s[j:j+len(suffix)] == suffix:
                        return True
        return False

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        dp = {}
        max_len = 1
        for i in range(len(nums)):
            curr = nums[i]
            new_dp = {}
            for j in range(i):
                prev = nums[j]
                diff = abs(curr - prev)
                # Find the maximum length of subsequences ending with a difference >= diff
                max_prev_len = 0
                for d in dp:
                    if d >= diff:
                        max_prev_len = max(max_prev_len, dp[d])
                new_dp[diff] = max(new_dp.get(diff, 0), max_prev_len + 1)
            # Update dp with new_dp
            for d in new_dp:
                dp[d] = max(dp.get(d, 0), new_dp[d])
            max_len = max(max_len, max(dp.values(), default=1))
        return max_len

class Solution:
    def maxLength(self, nums: List[int]) -> int:
        from math import gcd
        from functools import reduce

        def lcm(a, b):
            return a * b // gcd(a, b)

        max_len = 0
        n = len(nums)

        for i in range(n):
            current_gcd = nums[i]
            current_lcm = nums[i]
            current_product = nums[i]
            for j in range(i, n):
                current_gcd = gcd(current_gcd, nums[j])
                current_lcm = lcm(current_lcm, nums[j])
                current_product *= nums[j]
                if current_product == current_lcm * current_gcd:
                    max_len = max(max_len, j - i + 1)
        return max_len

class Solution:
    def calculateScore(self, s: str) -> int:
        # Create a mapping for the mirror of each letter
        mirror = {chr(ord('a') + i): chr(ord('a') + 25 - i) for i in range(26)}

        # Initialize a list to track marked indices
        marked = [False] * len(s)

        # Initialize the score
        score = 0

        # Iterate through the string from left to right
        for i in range(len(s)):
            # Find the closest unmarked index j < i with s[j] as the mirror of s[i]
            for j in range(i - 1, -1, -1):
                if not marked[j] and mirror[s[i]] == s[j]:
                    # Mark both indices
                    marked[i] = True
                    marked[j] = True
                    # Add the difference to the score
                    score += (i - j)
                    break

        return score

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        rows = len(grid)
        cols = len(grid[0])

        for i in range(rows):
            if i % 2 == 0:
                # Left to right traversal
                for j in range(0, cols, 2):
                    result.append(grid[i][j])
            else:
                # Right to left traversal
                for j in range(cols - 1, -1, -2):
                    result.append(grid[i][j])
        return result

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        import sys
        sys.setrecursionlimit(1000000)
        from collections import defaultdict, deque

        def is_valid(max_weight):
            # Build the graph with edges <= max_weight
            graph = defaultdict(list)
            for a, b, w in edges:
                if w <= max_weight:
                    graph[a].append(b)

            # Check if each node has at most threshold outgoing edges
            for node in graph:
                if len(graph[node]) > threshold:
                    return False

            # Check if all nodes can reach node 0
            # Reverse the graph and check if node 0 can reach all other nodes
            reverse_graph = defaultdict(list)
            for a, b, w in edges:
                if w <= max_weight:
                    reverse_graph[b].append(a)

            visited = [False] * n
            queue = deque([0])
            visited[0] = True
            while queue:
                node = queue.popleft()
                for neighbor in reverse_graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)

            return all(visited)

        # Binary search for the minimum possible maximum weight
        left, right = 1, 10**6
        answer = -1
        while left <= right:
            mid = (left + right) // 2
            if is_valid(mid):
                answer = mid
                right = mid - 1
            else:
                left = mid + 1

        return answer

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Precompute the required operations for each subarray
        # Using a sliding window approach
        left = 0
        res = 0
        ops = 0

        for right in range(n):
            # Calculate the number of operations needed to make nums[left..right] non-decreasing
            while left < right and nums[right] < nums[right - 1]:
                # Increment the current element to match the previous one
                ops += nums[right - 1] - nums[right]
                right -= 1

            # Check if the total operations are within the allowed limit
            if ops <= k:
                res += 1
            else:
                # Move the left pointer forward until the operations are within the limit
                while left < right and ops > k:
                    ops -= nums[left + 1] - nums[left]
                    left += 1
                if ops <= k:
                    res += 1

        return res

