class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        from collections import defaultdict

        # Build the adjacency list
        tree = defaultdict(list)
        for u, v, length in edges:
            tree[u].append((v, length))
            tree[v].append((u, length))

        max_length = 0
        min_nodes = 0

        def dfs(node, parent, visited_values, current_length, current_nodes):
            nonlocal max_length, min_nodes
            value = nums[node]
            if value in visited_values:
                return
            new_visited = visited_values.copy()
            new_visited.add(value)
            new_length = current_length + nums[node]
            new_nodes = current_nodes + 1

            # Update max_length and min_nodes
            if new_length > max_length:
                max_length = new_length
                min_nodes = new_nodes
            elif new_length == max_length:
                if new_nodes < min_nodes:
                    min_nodes = new_nodes

            for neighbor, length in tree[node]:
                if neighbor != parent:
                    dfs(neighbor, node, new_visited, new_length, new_nodes)

        # Start DFS from root (node 0)
        dfs(0, -1, set(), 0, 0)

        return [max_length, min_nodes]

class Solution:
    def subarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        total = 0
        for i in range(n):
            start = max(0, i - nums[i])
            total += prefix_sum[i + 1] - prefix_sum[start]

        return total

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Initialize DP table
        dp = [[[0] * 3 for _ in range(2)] for _ in range(n)]

        # Base case: first house
        for i in range(3):
            dp[0][0][i] = cost[0][i]

        # Fill DP table for the rest of the houses
        for i in range(1, n):
            for j in range(3):
                for k in range(3):
                    if j != k:
                        dp[i][0][j] = min(dp[i][0][j], dp[i - 1][0][k] + cost[i][j])

        # Handle the second half of the houses
        for i in range(n // 2):
            for j in range(3):
                for k in range(3):
                    if j != k:
                        dp[n - 1 - i][1][j] = min(dp[n - 1 - i][1][j], dp[i][0][k] + cost[n - 1 - i][j])

        # Find the minimum cost for the last house
        return min(dp[n - 1][1])

