            if (current_sum * 2 - total_sum) % 2 == 0:
                count += 1

        return count

class Solution:
    def supersequences(self, words: List[str]) -> List[List[int]]:
        from collections import defaultdict, Counter
        from itertools import product

        # Step 1: Build a graph where nodes represent characters and edges represent transitions
        graph = defaultdict(set)
        for word in words:
            u, v = word[0], word[1]
            graph[u].add(v)

        # Step 2: Find all unique characters used
        chars = set()
        for word in words:
            chars.add(word[0])
            chars.add(word[1])
        chars = sorted(chars)

        # Step 3: Generate all possible sequences using backtracking
        def backtrack(path, visited, start):
            if len(path) == len(chars):
                return [path[:]]
            results = []
            for char in chars:
                if char not in visited:
                    if not path or char in graph[path[-1]]:
                        visited.add(char)
                        path.append(char)
                        results += backtrack(path, visited, char)
                        path.pop()
                        visited.remove(char)
            return results

        # Step 4: Generate all valid sequences
        sequences = []
        for char in chars:
            sequences += backtrack([char], {char}, char)

        # Step 5: Filter out sequences that do not contain all words as subsequences
        valid_sequences = []
        for seq in sequences:
            valid = True
            for word in words:
                i = 0
                j = 0
                while i < len(seq) and j < len(word):
                    if seq[i] == word[j]:
                        j += 1
                    i += 1
                if j != len(word):
                    valid = False
                    break
            if valid:
                valid_sequences.append(seq)

        # Step 6: Remove duplicate sequences that are permutations of each other
        freqs = []
        seen = set()
        for seq in valid_sequences:
            freq = [0] * 26
            for c in seq:
                freq[ord(c) - ord('a')] += 1
            freq_tuple = tuple(freq)
            if freq_tuple not in seen:
                seen.add(freq_tuple)
                freqs.append(freq)

        return freqs

