class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        x, y = 0, 0
        max_dist = 0
        for ch in s:
            # Update position based on current direction
            if ch == 'N':
                y += 1
            elif ch == 'S':
                y -= 1
            elif ch == 'E':
                x += 1
            elif ch == 'W':
                x -= 1

            # Calculate current Manhattan distance
            current_dist = abs(x) + abs(y)
            max_dist = max(max_dist, current_dist)

            # If we have remaining changes, try to flip the direction to maximize distance
            if k > 0:
                # Try flipping the current direction
                if ch == 'N':
                    y -= 2  # Flip N to S
                elif ch == 'S':
                    y += 2  # Flip S to N
                elif ch == 'E':
                    x -= 2  # Flip E to W
                elif ch == 'W':
                    x += 2  # Flip W to E

                # Recalculate distance after flipping
                flipped_dist = abs(x) + abs(y)
                max_dist = max(max_dist, flipped_dist)

                # Decrement k as we used one change
                k -= 1

        return max_dist

class Solution:
    def maxDifference(self, s: str, k: int) -> int:
        max_diff = float('-inf')
        n = len(s)

        # Iterate over all possible starting indices
        for i in range(n):
            freq = {}
            # Iterate over all possible ending indices
            for j in range(i, n):
                char = s[j]
                freq[char] = freq.get(char, 0) + 1
                # Check if the current substring length is at least k
                if j - i + 1 >= k:
                    # Find characters with odd and even frequencies
                    odd_chars = []
                    even_chars = []
                    for ch in freq:
                        if freq[ch] % 2 == 1:
                            odd_chars.append(ch)
                        else:
                            even_chars.append(ch)
                    # If there are both odd and even frequency characters, compute differences
                    if odd_chars and even_chars:
                        for a in odd_chars:
                            for b in even_chars:
                                diff = freq[a] - freq[b]
                                if diff > max_diff:
                                    max_diff = diff
        return max_diff if max_diff != float('-inf') else -1

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        from collections import defaultdict

        # Create a mapping from element value to its smallest index
        element_map = defaultdict(lambda: float('inf'))
        for idx, val in enumerate(elements):
            if idx < element_map[val]:
                element_map[val] = idx

        # Assign elements to groups
        assigned = []
        for group in groups:
            found = False
            for val in element_map:
                if group % val == 0:
                    assigned.append(element_map[val])
                    found = True
                    break
            if not found:
                assigned.append(-1)
        return assigned

