class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        import bisect

        # Calculate the total area of all squares
        total_area = sum(l * l for x, y, l in squares)
        target_area = total_area / 2

        # Extract all unique y-coordinates from the squares (sorted)
        ys = sorted(set(y for x, y, l in squares))
        ys.append(ys[-1] + 1)  # Add a sentinel to handle upper bound

        # Binary search for the minimum y-coordinate
        left, right = 0, len(ys) - 1
        while left < right:
            mid = (left + right) // 2
            current_y = ys[mid]
            area_below = 0

            # Compute the area below the current y-coordinate
            for x, y, l in squares:
                if y + l <= current_y:
                    area_below += l * l
                elif y >= current_y:
                    continue
                else:
                    height = current_y - y
                    area_below += height * l

            if area_below < target_area:
                left = mid + 1
            else:
                right = mid

        # Return the corresponding y-coordinate with precision
        return float(ys[left])

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        import bisect

        # Step 1: Compute the total area
        total_area = 0
        for x, y, l in squares:
