class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        from collections import defaultdict

        # Step 1: Record the first and last occurrence of each character
        first_occurrence = {}
        last_occurrence = {}
        for i, ch in enumerate(s):
            if ch not in first_occurrence:
                first_occurrence[ch] = i
            last_occurrence[ch] = i

        # Step 2: Find all possible special substrings
        special_substrings = []
        used = [False] * len(s)

        for i in range(len(s)):
            if used[i]:
                continue
            chars_in_substring = set()
            j = i
            while j < len(s):
                ch = s[j]
                if ch in chars_in_substring:
                    break
                # Check if any character in the current substring appears outside of it
                if any(first_occurrence[c] < i or last_occurrence[c] > j for c in chars_in_substring):
                    break
                chars_in_substring.add(ch)
                j += 1
            if j - i > 1 and j - i <= len(s) - 1:
                special_substrings.append((i, j - 1))
                # Mark the indices as used
                for idx in range(i, j):
                    used[idx] = True

        # Step 3: Greedily select non-overlapping special substrings
        count = 0
        i = 0
        while i < len(s):
            if not used[i]:
                # Try to find the smallest valid special substring starting at i
                found = False
                for j in range(i + 1, len(s) + 1):
                    if (i, j - 1) in special_substrings:
                        count += 1
                        # Mark the indices as used
                        for idx in range(i, j):
                            used[idx] = True
                        i = j
                        found = True
                        break
                if not found:
                    i += 1
            else:
                i += 1

        return count >= k

class Solution:
    def longestCommonPrefix(self, s: str, t: str) -> int:
        # Find the initial common prefix length
        common_len = 0
        while common_len < len(s) and common_len < len(t) and s[common_len] == t[common_len]:
            common_len += 1

        # If the entire string is a common prefix, return it
        if common_len == len(s) or common_len == len(t):
            return common_len

        # Try removing each character from s and compute the new common prefix
        max_len = 0
        for i in range(len(s)):
            # Create s' by removing the i-th character
            s_prime = s[:i] + s[i+1:]
            # Compute the common prefix length between s' and t
            current_len = 0
            while current_len < len(s_prime) and current_len < len(t) and s_prime[current_len] == t[current_len]:
                current_len += 1
            max_len = max(max_len, current_len)

        return max_len

