        points.sort()

        # Function to check if it's possible to select k points with min distance >= d
        def is_possible(d):
            count = 1
            last = points[0]
            for p in points[1:]:
                if abs(p[0] - last[0]) + abs(p[1] - last[1]) >= d:
                    count += 1
                    last = p
                    if count == k:
                        return True
