class Solution:
    def maxCoins(self, lane1: List[int], lane2: List[int]) -> int:
        n = len(lane1)

        # Compute prefix sums for both lanes
        prefix1 = [0] * (n + 1)
        prefix2 = [0] * (n + 1)

        for i in range(n):
            prefix1[i + 1] = prefix1[i] + lane1[i]
            prefix2[i + 1] = prefix2[i] + lane2[i]

        max_coins = float('-inf')

        # Case 1: No lane switches (Mario stays in lane 1 or lane 2)
        for i in range(1, n + 1):
            max_coins = max(max_coins, prefix1[i], prefix2[i])

        # Case 2: One lane switch
        # Start in lane 1, switch to lane 2
        for i in range(1, n):
            for j in range(i + 1, n + 1):
                total = prefix1[i] + prefix2[j] - prefix2[i]
                max_coins = max(max_coins, total)

        # Start in lane 2, switch to lane 1
        for i in range(1, n):
            for j in range(i + 1, n + 1):
                total = prefix2[i] + prefix1[j] - prefix1[i]
                max_coins = max(max_coins, total)

        # Case 3: Two lane switches
        # Start in lane 1, switch to lane 2, switch back to lane 1
        for i in range(1, n):
            for j in range(i + 1, n):
                for k in range(j + 1, n + 1):
                    total = prefix1[i] + (prefix2[j] - prefix2[i]) + (prefix1[k] - prefix1[j])
                    max_coins = max(max_coins, total)

        # Start in lane 2, switch to lane 1, switch back to lane 2
        for i in range(1, n):
            for j in range(i + 1, n):
                for k in range(j + 1, n + 1):
                    total = prefix2[i] + (prefix1[j] - prefix1[i]) + (prefix2[k] - prefix2[j])
                    max_coins = max(max_coins, total)

        return max_coins

class Solution:
    def transformArray(self, nums: List[int]) -> List[int]:
        transformed = []
        for num in nums:
            if num % 2 == 0:
                transformed.append(0)
            else:
                transformed.append(1)
        transformed.sort()
        return transformed

class Solution:
    def minCost(self, nums: List[int]) -> int:
        from functools import lru_cache

        @lru_cache(None)
        def dp(i):
            if i >= len(nums):
                return 0
            if len(nums) - i <= 2:
                return max(nums[i:])
            # Consider all combinations of removing two elements from the first three
            option1 = max(nums[i], nums[i+1]) + dp(i+2)
            option2 = max(nums[i], nums[i+2]) + dp(i+3)
            option3 = max(nums[i+1], nums[i+2]) + dp(i+3)
            return min(option1, option2, option3)

        return dp(0)

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        from math import factorial
        from typing import List

        # Helper function to check if a permutation is alternating
        def is_alternating(perm):
            for i in range(len(perm) - 1):
                if (perm[i] % 2 == perm[i + 1] % 2):
                    return False
            return True

        # Helper function to generate permutations in lex order
        def backtrack(start, path, used):
            if len(path) == n:
                if is_alternating(path):
                    self.count += 1
                    if self.count == k:
                        self.result = path.copy()
                        return True
                return False

            for i in range(1, n + 1):
                if not used[i]:
                    used[i] = True
                    path.append(i)
                    if backtrack(start + 1, path, used):
                        return True
                    path.pop()
                    used[i] = False
            return False

        self.count = 0
        self.result = []
        used = [False] * (n + 1)
        backtrack(1, [], used)

        return self.result if self.count >= k else []

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        from collections import defaultdict

        n = len(nums)
        freq = defaultdict(int)

        # Generate all subarrays of size k
        for i in range(n - k + 1):
            subarray = nums[i:i + k]
            sub_freq = defaultdict(int)
            for num in subarray:
                sub_freq[num] += 1
            # Update global frequency
            for num, count in sub_freq.items():
                freq[num] += count

        # Find the largest integer with frequency exactly 1
        candidates = [num for num, count in freq.items() if count == 1]
        if not candidates:
            return -1
        return max(candidates)

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # Precompute the cost to convert one character to another
        def get_cost(c1, c2):
            return min(abs(ord(c1) - ord(c2)), 26 - abs(ord(c1) - ord(c2)))

        # Initialize a 3D DP array: dp[i][j][cost] = max length of palindromic subsequence from i to j with 'cost' operations
        dp = [[[0] * (k + 1) for _ in range(n)] for __ in range(n)]

        # Base case: single character
        for i in range(n):
            for cost in range(k + 1):
                dp[i][i][cost] = 1

        # Fill the DP table
        for length in range(2, n + 1):  # length of substring
            for i in range(n - length + 1):
                j = i + length - 1
                for cost in range(k + 1):
                    # Case 1: Do not use s[i] and s[j]
                    dp[i][j][cost] = dp[i + 1][j - 1][cost] if j > i + 1 else 0
                    # Case 2: Use s[i] and s[j], check if they can be made equal within the cost
                    for c1 in range(26):
                        for c2 in range(26):
                            current_cost = get_cost(chr(ord('a') + c1), chr(ord('a') + c2))
                            if current_cost <= cost:
                                new_cost = cost - current_cost
                                val = 2 + dp[i + 1][j - 1][new_cost] if j > i + 1 else 2
                                dp[i][j][cost] = max(dp[i][j][cost], val)

        # Find the maximum value across all substrings and costs up to k
        result = 0
        for i in range(n):
            for j in range(n):
                for cost in range(k + 1):
                    result = max(result, dp[i][j][cost])
        return result

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        # Precompute prefix sums
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        # Initialize DP table
        dp = [[float('-inf')] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(k + 1):
                # Case 1: Do not use the ith element
                dp[i][j] = dp[i - 1][j]

                # Case 2: Use the ith element as part of a subarray
                if j > 0:
                    for l in range(m, i + 1):
                        # Subarray from i - l to i - 1
                        subarray_sum = prefix[i] - prefix[i - l]
                        if dp[i - l][j - 1] + subarray_sum > dp[i][j]:
                            dp[i][j] = dp[i - l][j - 1] + subarray_sum

        return dp[n][k]

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        length = n + m - 1
        result = ['a'] * length

        # Apply constraints from str1
        for i in range(n):
            start = i
            end = i + m
            if end > length:
                continue
            if str1[i] == 'T':
                for j in range(m):
                    result[start + j] = str2[j]
            else:
                # Ensure the substring does not match str2
                pass

        # Check for validity
        for i in range(n):
            start = i
            end = i + m
            if end > length:
                continue
            substring = ''.join(result[start:end])
            if str1[i] == 'T' and substring != str2:
                return ""
            if str1[i] == 'F' and substring == str2:
                return ""

        return ''.join(result)

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        # Pair each basket with its index and sort by capacity
        sorted_baskets = sorted([(capacity, idx) for idx, capacity in enumerate(baskets)], key=lambda x: x[0])

        # Track which baskets have been used
        used_baskets = set()

        unplaced_count = 0

        for fruit in fruits:
            placed = False
            for capacity, idx in sorted_baskets:
                if idx not in used_baskets and capacity >= fruit:
                    used_baskets.add(idx)
                    placed = True
                    break
            if not placed:
                unplaced_count += 1

        return unplaced_count

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        # Sort baskets in ascending order
        baskets.sort()
        n = len(fruits)
        unplaced = 0
        basket_idx = 0

        for fruit in fruits:
            # Find the leftmost basket with capacity >= fruit
            while basket_idx < n and baskets[basket_idx] < fruit:
                basket_idx += 1
            if basket_idx < n:
                # Place the fruit in the basket
                basket_idx += 1
            else:
                # No available basket for this fruit
                unplaced += 1

        return unplaced

class Solution:
    def applySubstitutions(self, replacements: List[List[str]], text: str) -> str:
        # Convert replacements to a dictionary
        replacement_dict = {key: value for key, value in replacements}

        # Continue substituting until no placeholders remain
        while True:
            # Check if any placeholder exists in the text
            if "%%" not in text:
                break

            # Replace all placeholders in one pass
            for key in replacement_dict:
                placeholder = f"%{key}%"
                text = text.replace(placeholder, replacement_dict[key])

        return text

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        from itertools import permutations

        valid_numbers = set()

        # Generate all possible 3-digit permutations
        for p in permutations(digits, 3):
            # Skip if the first digit is zero
            if p[0] == 0:
                continue
            # Check if the last digit is even
            if p[2] % 2 == 0:
                # Convert the permutation to a number and add to the set
                number = p[0] * 100 + p[1] * 10 + p[2]
                valid_numbers.add(number)

        return len(valid_numbers)

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        from collections import defaultdict

        # Build a trie structure
        class TrieNode:
            def __init__(self):
                self.children = defaultdict(TrieNode)
                self.count = 0

        root = TrieNode()

        # Insert all words into the trie
        for word in words:
            node = root
            for ch in word:
                node = node.children[ch]
                node.count += 1

        # Find the maximum prefix length that appears at least k times
        def get_max_prefix_length(node, depth):
            if node.count >= k:
                return depth
            max_len = 0
            for child in node.children.values():
                max_len = max(max_len, get_max_prefix_length(child, depth + 1))
            return max_len

        result = []
        for i in range(len(words)):
            # Simulate removing words[i]
            word_to_remove = words[i]
            # Rebuild the trie without the current word
            new_root = TrieNode()
            for j in range(len(words)):
                if j == i:
                    continue
                word = words[j]
                node = new_root
                for ch in word:
                    node = node.children[ch]
                    node.count += 1
            # Compute the maximum prefix length
            max_len = get_max_prefix_length(new_root, 0)
            result.append(max_len)

        return result

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        from collections import defaultdict
        import sys

        sys.setrecursionlimit(100000)

        # Build the tree as an adjacency list
        tree = defaultdict(list)
        for u, v, length in edges:
            tree[u].append((v, length))
            tree[v].append((u, length))

        max_length = 0
        min_nodes = 0

        def dfs(node, parent, path_values, path_length, node_count):
            nonlocal max_length, min_nodes
            # Add current node's value to the path
            current_value = nums[node]
            new_path_values = path_values + [current_value]
            new_path_length = path_length + 1
            new_node_count = node_count + 1

            # Check if the path is valid (all values are unique or exactly one value appears twice)
            value_counts = {}
            duplicate_found = False
            for val in new_path_values:
                if val in value_counts:
                    if value_counts[val] == 1:
                        duplicate_found = True
                    else:
                        # More than one duplicate found, invalid path
                        return
                    value_counts[val] += 1
                else:
                    value_counts[val] = 1

            if not duplicate_found:
                # Valid path
                if new_path_length > max_length:
                    max_length = new_path_length
                    min_nodes = new_node_count
                elif new_path_length == max_length:
                    if new_node_count < min_nodes:
                        min_nodes = new_node_count
            else:
                # Only one duplicate allowed, check if it's valid
                if sum(1 for count in value_counts.values() if count == 2) <= 1:
                    if new_path_length > max_length:
                        max_length = new_path_length
                        min_nodes = new_node_count
                    elif new_path_length == max_length:
                        if new_node_count < min_nodes:
                            min_nodes = new_node_count

            # Recursively visit children
            for neighbor, length in tree[node]:
                if neighbor != parent:
                    dfs(neighbor, node, new_path_values, new_path_length, new_node_count)

        # Start DFS from the root node (node 0)
        dfs(0, -1, [], 0, 0)

        return [max_length, min_nodes]

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        max_sum = float('-inf')
        n = len(nums)

        for i in range(n):
            seen = set()
            current_sum = 0
            for j in range(i, n):
                if nums[j] in seen:
                    break
                seen.add(nums[j])
                current_sum += nums[j]
                max_sum = max(max_sum, current_sum)

        return max_sum

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        delta = [0] * (n + 1)  # To handle range updates efficiently
        for k in range(len(queries)):
            l, r, val = queries[k]
            delta[l] += val
            delta[r + 1] -= val

            # Apply the current delta to compute the cumulative effect
            curr = 0
            for i in range(n):
                curr += delta[i]
                if nums[i] - curr < 0:
                    break
            else:
                return k + 1  # All elements are zero after this query

        return -1

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        count = 0
        for num in range(l, r + 1):
            digits = [int(d) for d in str(num)]
            product = 1
            for d in digits:
                product *= d
            total = sum(digits)
            if total != 0 and product % total == 0:
                count += 1
        return count

class Solution:
    def phonePrefix(self, numbers: List[str]) -> bool:
        for i in range(len(numbers)):
            for j in range(len(numbers)):
                if i != j and numbers[i].startswith(numbers[j]):
                    return False
        return True

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        total_cells = n * n
        max_containers_by_weight = maxWeight // w
        return min(total_cells, max_containers_by_weight)

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # Convert each list to a set for efficient intersection calculation
        sets = [set(arr) for arr in properties]

        # Union-Find (Disjoint Set Union) data structure
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]  # Path compression
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u != root_v:
                parent[root_v] = root_u

        # Check all pairs of nodes
        for i in range(n):
            for j in range(i + 1, n):
                # Compute the size of the intersection
                common = len(sets[i] & sets[j])
                if common >= k:
                    union(i, j)

        # Count the number of unique roots
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        # Memoization table
        memo = [[-1 for _ in range(n)] for _ in range(n)]

        def dp(i, j):
            if i >= j:
                return 0
            if memo[i][j] != -1:
                return memo[i][j]

            # Option 1: Remove first two elements
            option1 = dp(i + 2, j) + nums[i] + nums[i + 1]

            # Option 2: Remove last two elements
            option2 = dp(i, j - 2) + nums[j] + nums[j - 1]

            # Option 3: Remove first and last elements
            option3 = dp(i + 1, j - 1) + nums[i] + nums[j]

            memo[i][j] = max(option1, option2, option3)
            return memo[i][j]

        return dp(0, n - 1)

class Solution:
    def reverseDegree(self, s: str) -> int:
        total = 0
        for i, ch in enumerate(s, start=1):
            reversed_pos = 26 - (ord(ch) - ord('a'))
            total += reversed_pos * i
        return total

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        # Step 1: Augment the string
        t = '1' + s + '1'

        # Step 2: Find all valid 1-blocks surrounded by 0s
        ones_blocks = []
        i = 0
        while i < len(t):
            if t[i] == '1':
                start = i
                while i < len(t) and t[i] == '1':
                    i += 1
                end = i
                # Check if this block is surrounded by 0s
                if start > 0 and t[start - 1] == '0' and end < len(t) and t[end] == '0':
                    ones_blocks.append((start, end))
            else:
                i += 1

        # Step 3: Find all valid 0-blocks surrounded by 1s
        zeros_blocks = []
        i = 0
        while i < len(t):
            if t[i] == '0':
                start = i
                while i < len(t) and t[i] == '0':
                    i += 1
                end = i
                # Check if this block is surrounded by 1s
                if start > 0 and t[start - 1] == '1' and end < len(t) and t[end] == '1':
                    zeros_blocks.append((start, end))
            else:
                i += 1

        # Step 4: Calculate the base count of active sections
        base_count = sum(1 for ch in s if ch == '1')

        # Step 5: Try all possible trades and compute the maximum gain
        max_gain = 0
        for one_start, one_end in ones_blocks:
            # Convert this 1-block to 0s
            # Count how many 1s are removed
            removed_ones = one_end - one_start
            # Now look for the best 0-block to convert to 1s
            for zero_start, zero_end in zeros_blocks:
                # Count how many 0s are converted to 1s
                added_ones = zero_end - zero_start
                # Compute the net gain
                gain = added_ones - removed_ones
                if gain > max_gain:
                    max_gain = gain

        # Step 6: Return the maximum number of active sections
        return base_count + max_gain

class Solution:
    def minCosts(self, cost: List[int]) -> List[int]:
        n = len(cost)
        answer = [0] * n
        answer[0] = cost[0]

        for i in range(1, n):
            answer[i] = min(answer[i-1], cost[i])

        return answer

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def is_palindrome(string):
            return string == string[::-1]

        max_len = 0

        # Generate all substrings from s
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                substr_s = s[i:j]

                # Generate all substrings from t
                for k in range(len(t)):
                    for l in range(k + 1, len(t) + 1):
                        substr_t = t[k:l]

                        # Concatenate substrings and check for palindrome
                        combined = substr_s + substr_t
                        if is_palindrome(combined):
                            max_len = max(max_len, len(combined))

        return max_len

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        max_len = 0
        # Check for palindromes formed by combining prefixes of s and suffixes of t
        for i in range(len(s)):
            for j in range(len(t)):
                # Start with the current character from s and t
                left, right = i, j
                count = 0
                while left < len(s) and right < len(t) and s[left] == t[right]:
                    count += 1
                    left += 1
                    right += 1
                # Update max_len if needed
                max_len = max(max_len, count)

        # Check for palindromes entirely within s
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                substr = s[i:j]
                if substr == substr[::-1]:
                    max_len = max(max_len, len(substr))

        # Check for palindromes entirely within t
        for i in range(len(t)):
            for j in range(i + 1, len(t) + 1):
                substr = t[i:j]
                if substr == substr[::-1]:
                    max_len = max(max_len, len(substr))

        return max_len
